(()=>{const A='#e1c08e',reduce=matchMedia('(prefers-reduced-motion:reduce)').matches,b=document.body,s=document.createElement('style');s.textContent=`body{background:#020202;color:#f5f0e8}body:before{content:'';position:fixed;inset:0;pointer-events:none;z-index:-3;background:radial-gradient(ellipse at 50% 38%,#d9ae7312,transparent 36%),radial-gradient(ellipse at 50% 0,#ffffff06,transparent 48%);mix-blend-mode:screen}.fx-progress{position:fixed;top:0;left:0;width:100%;height:2px;background:#fff1;z-index:100}.fx-progress i{display:block;height:100%;width:0;background:${A};box-shadow:0 0 14px ${A}}.fx-projector-light{position:fixed;left:50%;top:42%;width:2px;height:2px;border-radius:50%;background:#fff;box-shadow:0 0 150px 70px ${A}25;pointer-events:none;z-index:0;animation:lamp 3s ease-in-out infinite}.fx-projector-light:after{content:'';position:absolute;width:78vw;height:55vh;left:-39vw;top:0;background:linear-gradient(180deg,#fff2,transparent);clip-path:polygon(50% 0,100% 100%,0 100%);opacity:.3}.fx-reveal{opacity:0;transform:translateY(35px) scale(.985);transition:opacity 1s ease,transform 1s cubic-bezier(.2,.8,.2,1)}.fx-visible{opacity:1!important;transform:none!important}.projector.show .beam{animation:beam 1.2s ease both}.projected.on{animation:project .9s ease both}.film-count{animation:count 1s ease}.fx-dust,.fx-particle,.fx-scratch,.fx-leak{position:fixed;pointer-events:none}.fx-dust{width:clamp(2px,.28vw,4px);height:clamp(2px,.28vw,4px);border-radius:50%;background:#fff;opacity:0;animation:dust 5s linear infinite}.fx-particle{width:3px;height:3px;border-radius:50%;background:${A};box-shadow:0 0 12px ${A};opacity:0;animation:particle 8s ease-in-out infinite}.fx-scratch{height:1px;width:35px;background:#fff;opacity:.05;animation:scratch 6s linear infinite}.fx-leak{inset:-10%;background:radial-gradient(ellipse at 15% 40%,#e9a45a14,transparent 18%),radial-gradient(ellipse at 85% 65%,#b9d7ff0c,transparent 16%);mix-blend-mode:screen;opacity:.4;animation:leak 9s ease-in-out infinite}.film-frame{position:relative}.film-frame:after{content:'';position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 90px #0008}@keyframes lamp{50%{opacity:.55;transform:scale(1.25)}}@keyframes beam{from{opacity:0;transform:scaleX(.3)}to{opacity:1;transform:scaleX(1)}}@keyframes project{0%{opacity:0;filter:blur(8px);transform:scale(.96)}60%{opacity:1;filter:blur(0);transform:scale(1.02)}100%{transform:none}}@keyframes count{50%{transform:scale(1.15);opacity:.6}}@keyframes dust{0%{transform:translate3d(-15px,25vh,0);opacity:0}20%{opacity:.5}100%{transform:translate3d(30px,-25vh,0);opacity:0}}@keyframes particle{0%{transform:translate3d(0,25vh,0) scale(.2);opacity:0}20%{opacity:.5}55%{transform:translate3d(-25px,-35vh,0) scale(1)}100%{transform:translate3d(25px,-85vh,0) scale(.1);opacity:0}}@keyframes scratch{0%{transform:translateX(-120vw);opacity:0}20%{opacity:.08}50%{opacity:.03}100%{transform:translateX(120vw);opacity:0}}@keyframes leak{50%{transform:translateX(3%) scale(1.05);opacity:.7}}@media(prefers-reduced-motion:reduce){.fx-dust,.fx-particle,.fx-scratch,.fx-leak{display:none}}`;b.appendChild(s);const p=document.createElement('div');p.className='fx-progress';p.innerHTML='<i></i>';b.appendChild(p);const l=document.createElement('div');l.className='fx-projector-light';b.appendChild(l);if(!reduce){const leak=document.createElement('div');leak.className='fx-leak';b.appendChild(leak);for(let i=0;i<28;i++){const d=document.createElement('span');d.className='fx-dust';d.style.left=Math.random()*100+'%';d.style.top=Math.random()*100+'%';d.style.animationDelay=-Math.random()*5+'s';b.appendChild(d)}for(let i=0;i<36;i++){const x=document.createElement('i');x.className='fx-particle';x.style.left=Math.random()*100+'%';x.style.bottom=-5-Math.random()*20+'px';x.style.animationDelay=-Math.random()*8+'s';x.style.animationDuration=6+Math.random()*5+'s';b.appendChild(x)}for(let i=0;i<10;i++){const x=document.createElement('i');x.className='fx-scratch';x.style.top=Math.random()*100+'%';x.style.animationDelay=-Math.random()*6+'s';b.appendChild(x)}}document.querySelectorAll('section').forEach(s=>s.classList.add('fx-reveal'));const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('fx-visible');io.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.fx-reveal').forEach(e=>io.observe(e));addEventListener('scroll',()=>{const max=document.documentElement.scrollHeight-innerHeight;p.firstElementChild.style.width=(max?scrollY/max*100:0)+'%'})})();